import os

print("=== Workspace files ===")
for root, dirs, files in os.walk("."):
    if ".codex" in root:
        continue
    for f in files:
        full = os.path.join(root, f)
        print(full, os.path.getsize(full))

print("\n=== Skill scripts ===")
skill_dir = ".codex/skills/pdf/scripts"
if os.path.isdir(skill_dir):
    for f in sorted(os.listdir(skill_dir)):
        print(f)
else:
    print("No scripts dir at", skill_dir)
